import{_ as a,o as e,c as r,a4 as o}from"./chunks/framework.9tZL7ZIQ.js";const f=JSON.parse('{"title":"蓝筹印花（Blue Chip Stamps）","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/蓝筹印花.md","filePath":"03_companies/蓝筹印花.md"}'),l={name:"03_companies/蓝筹印花.md"};function i(s,t,h,d,n,u){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="蓝筹印花-blue-chip-stamps" tabindex="-1">蓝筹印花（Blue Chip Stamps） <a class="header-anchor" href="#蓝筹印花-blue-chip-stamps" aria-label="Permalink to &quot;蓝筹印花（Blue Chip Stamps）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>Blue Chip Stamps</td></tr><tr><td>行业</td><td>零售印花业务 → 投资控股</td></tr><tr><td>总部</td><td>加利福尼亚州洛杉矶</td></tr><tr><td>成立年份</td><td>1956年</td></tr><tr><td>合并年份</td><td>1983年（并入<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>）</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><h3 id="起源与商业模型" tabindex="-1">起源与商业模型 <a class="header-anchor" href="#起源与商业模型" aria-label="Permalink to &quot;起源与商业模型&quot;">​</a></h3><ul><li>1956年成立，是一家零售印花公司</li><li>消费者在合作商户购物获赠印花，收集后兑换相应商品</li><li>1960年代高峰期：年收入超过1.2亿美元，是当时美国最大的印花公司之一</li></ul><h3 id="业务衰退" tabindex="-1">业务衰退 <a class="header-anchor" href="#业务衰退" aria-label="Permalink to &quot;业务衰退&quot;">​</a></h3><ul><li>1970年代后，信用卡和折扣零售兴起，印花业务持续大幅萎缩</li><li>但公司积累了大量浮存金（float），成为可用以收购实业企业的投资资本</li><li>这一&quot;衰落业务+浮存金投资&quot;的双轨结构，正是巴菲特和芒格看中的核心价值</li></ul><h2 id="收购时间线" tabindex="-1">收购时间线 <a class="header-anchor" href="#收购时间线" aria-label="Permalink to &quot;收购时间线&quot;">​</a></h2><h3 id="巴菲特入股-1968-1970年代初期" tabindex="-1">巴菲特入股（1968-1970年代初期） <a class="header-anchor" href="#巴菲特入股-1968-1970年代初期" aria-label="Permalink to &quot;巴菲特入股（1968-1970年代初期）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>年份</th><th>事件</th></tr></thead><tbody><tr><td><strong>1969</strong></td><td>蓝筹印花曾计划通过美林证券牵头进行IPO，发行价约每股24美元。但因道琼斯指数大跌，承销商称发行价不可行，巴菲特撤回了发行。这是蓝筹印花历史上唯一一次IPO尝试。巴菲特当时持有大量合伙公司股票，等待更有利的出售时机。</td></tr><tr><td><strong>1970年前后</strong></td><td>巴菲特通过<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>保险子公司和多元零售公司（Diversified Retailing Company）开始买入蓝筹印花股份</td></tr><tr><td><strong>1973</strong></td><td>巴菲特持有的蓝筹印花股份约19%，年末后进一步增持至约22.5%</td></tr><tr><td><strong>1974</strong></td><td>年末持股比例约25.5%，印花销售额持续大幅下滑</td></tr><tr><td><strong>1976</strong></td><td>年末持股约33%（仅计算流通股）</td></tr><tr><td><strong>1977</strong></td><td>年末持股约36.5%，蓝筹印花当年运营盈利约1,290万美元，另有410万美元证券收益</td></tr><tr><td><strong>1978</strong></td><td><strong>关键节点</strong>：<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>与多元零售公司合并，持股提升至约58%，必须完全合并报表</td></tr></tbody></table><blockquote><p>&quot;年底与多元零售公司合并，给我们的财务业绩披露带来两个新问题。合并后，我们对<a href="/03_companies/蓝筹印花">蓝筹印花</a>的持股提升到约58%，因此该公司的账目必须完全合并到<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>的资产负债表和利润表中。&quot; —— <a href="/search?q=1978年">1978年</a>股东信</p></blockquote><h3 id="关键收购-1970s-1980s" tabindex="-1">关键收购（1970s-1980s） <a class="header-anchor" href="#关键收购-1970s-1980s" aria-label="Permalink to &quot;关键收购（1970s-1980s）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>年份</th><th>收购标的</th><th>价格</th><th>备注</th></tr></thead><tbody><tr><td><strong>1972</strong></td><td><a href="/03_companies/喜诗糖果">喜诗糖果</a></td><td>2,500万美元</td><td>蓝筹印花最成功的收购，成为巴菲特投资理念的转折点</td></tr><tr><td><strong>1977</strong></td><td><a href="/03_companies/水牛城新闻">水牛城新闻</a>（Buffalo Evening News）</td><td>—</td><td>收购后推出周日版，与Courier-Express激烈竞争</td></tr><tr><td>1970s</td><td>韦斯考金融公司（Wesco Financial）80%股权</td><td>—</td><td>路易·文辛蒂管理，主营储贷业务</td></tr><tr><td>1970s</td><td>创办/收购约6家其他小企业</td><td>—</td><td>全部现金谈判收购，几乎无例外卖家非常诚实公平</td></tr></tbody></table><blockquote><p>&quot;从纺织基础出发，我们<a href="/03_companies/蓝筹印花">蓝筹印花</a>和韦斯考子公司通过现金谈判从私人所有者手里收购了13家企业全部所有权，还创办了另外6家。&quot; —— <a href="/search?q=1979年">1979年</a>股东信</p></blockquote><h3 id="与伯克希尔哈撒韦合并-1983年" tabindex="-1">与<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>合并（1983年） <a class="header-anchor" href="#与伯克希尔哈撒韦合并-1983年" aria-label="Permalink to &quot;与[[伯克希尔哈撒韦]]合并（1983年）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>合并时间</td><td>1983年年中完成</td></tr><tr><td>合并方式</td><td>换股合并（60%现金 + 40%伯克希尔股票）</td></tr><tr><td>合并效果</td><td>蓝筹印花成为<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>全资子公司</td></tr><tr><td>商誉处理</td><td><a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>以&quot;购买法&quot;入账，产生约5,170万美元商誉</td></tr></tbody></table><blockquote><p>&quot;1983年<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>收购了<a href="/03_companies/蓝筹印花">蓝筹印花</a>邮票剩余的40%股份……我们给<a href="/03_companies/蓝筹印花">蓝筹印花</a>邮票股东的股票的&#39;公允价值&#39;，必须分摊到收购来的净资产上。我们&#39;支付&#39;的价格比我们拿到的可辨认净资产高出5,170万美元，这部分溢价分成两块商誉：2,840万美元归<a href="/03_companies/喜诗糖果">喜诗糖果</a>，2,330万美元归《<a href="/03_companies/水牛城新闻">水牛城新闻</a>》晚报。&quot; —— <a href="/search?q=1983年">1983年</a>股东信</p></blockquote><h2 id="旗下核心子公司" tabindex="-1">旗下核心子公司 <a class="header-anchor" href="#旗下核心子公司" aria-label="Permalink to &quot;旗下核心子公司&quot;">​</a></h2><h3 id="喜诗糖果-see-s-candies-——-蓝筹印花的明珠" tabindex="-1"><a href="/03_companies/喜诗糖果">喜诗糖果</a>（See&#39;s Candies）—— 蓝筹印花的明珠 <a class="header-anchor" href="#喜诗糖果-see-s-candies-——-蓝筹印花的明珠" aria-label="Permalink to &quot;[[喜诗糖果]]（See&#39;s Candies）—— 蓝筹印花的明珠&quot;">​</a></h3><ul><li><strong>收购价格</strong>：2,500万美元（1972年1月3日完成交割）</li><li><strong>收购时状况</strong>：净资产约800万美元，税后盈利约200万美元</li><li><strong>战略意义</strong>：巴菲特从&quot;雪茄烟蒂&quot;投资转向&quot;优质企业&quot;投资的关键转折点</li></ul><blockquote><p>&quot;二十年前，1972年1月3日，蓝筹印花买了喜诗糖果，当时卖家要四千万，企业净现金一千万，所以实际卖价三千万。查理和我那时候还不懂经济特许经营权，我们看七百万净资产，我们出价两千五百万，就不动了，卖家居然接受了，我们幸运。&quot; —— <a href="/search?q=1991年">1991年</a>股东信</p></blockquote><ul><li><strong>业绩增长</strong>： <ul><li>收购后税前利润从420万美元增长至1,260万美元（1977年），几乎无需额外资本投入</li><li>到2014年（收购42周年），累计产生19亿美元税前利润，增长仅需追加4,000万美元</li><li>自购买以来，账面有形净资产（扣除现金后）长期低于零</li></ul></li></ul><h3 id="水牛城新闻-buffalo-news-——-竞争取胜的报纸" tabindex="-1"><a href="/03_companies/水牛城新闻">水牛城新闻</a>（Buffalo News）—— 竞争取胜的报纸 <a class="header-anchor" href="#水牛城新闻-buffalo-news-——-竞争取胜的报纸" aria-label="Permalink to &quot;[[水牛城新闻]]（Buffalo News）—— 竞争取胜的报纸&quot;">​</a></h3><ul><li><strong>收购时间</strong>：1977年</li><li><strong>早期困境</strong>：1977-1982年与Courier-Express激烈竞争，持续亏损 <ul><li>1981年税前亏损106万美元</li><li>1982年税前亏损122万美元</li></ul></li><li><strong>转折点</strong>：1983年Courier-Express关门，水牛城新闻成为唯一日报，当年实现盈利，利润率约10%</li><li><strong>竞争优势</strong>：平日渗透率美国前100大报纸排名第一；新闻洞占比50.9%（行业平均仅35-40%）</li><li><strong>最终出售</strong>：2012年出售给Lee Enterprises（报业收缩战略的一部分）</li></ul><blockquote><p>&quot;我相信你会发现<a href="/03_companies/蓝筹印花">蓝筹印花</a>对<a href="/03_companies/水牛城新闻">水牛城新闻</a>报纸发展的记录特别有意思。美国现在只有14个城市，日报周中发行量超过<a href="/03_companies/水牛城新闻">水牛城新闻</a>。但真正亮点是周日发行量增长。六年前，我们推出<a href="/03_companies/水牛城新闻">水牛城新闻</a>周日版之前……周日发行量36.7万，增长35%——尽管主要发行区域家庭数量六年几乎没变化。&quot; —— <a href="/search?q=1982年">1982年</a>股东信</p></blockquote><h3 id="韦斯考金融公司-wesco-financial-——-储贷业务平台" tabindex="-1">韦斯考金融公司（Wesco Financial）—— 储贷业务平台 <a class="header-anchor" href="#韦斯考金融公司-wesco-financial-——-储贷业务平台" aria-label="Permalink to &quot;韦斯考金融公司（Wesco Financial）—— 储贷业务平台&quot;">​</a></h3><ul><li><strong>持股</strong>：80%（<a href="/04_people/查理·芒格">查理·芒格</a>担任董事长）</li><li><strong>管理层</strong>：路易·文辛蒂（Louis Vinceanti）</li><li><strong>主营</strong>：储蓄贷款业务（储贷危机时代的优质参与者）</li><li><strong>1983年后</strong>：伯克希尔对其权益从48%提升至80%</li></ul><h2 id="管理团队" tabindex="-1">管理团队 <a class="header-anchor" href="#管理团队" aria-label="Permalink to &quot;管理团队&quot;">​</a></h2><table tabindex="0"><thead><tr><th>姓名</th><th>职位</th><th>贡献</th></tr></thead><tbody><tr><td><a href="/04_people/查理·芒格">查理·芒格</a></td><td>董事长</td><td>长期担任董事长，是蓝筹印花的灵魂人物；<a href="/search?q=1978年">1978年</a>股东信中被称为&quot;蓝筹印花董事长&quot;；设计股东指定捐赠计划</td></tr><tr><td>Robert H. Bird</td><td>高管</td><td>董事会秘书，负责日常运营报告；股东信中多次提及</td></tr><tr><td>Chuck Huggins</td><td><a href="/03_companies/喜诗糖果">喜诗糖果</a>总经理（1972-2006）</td><td>34年任期，利润增长十倍以上</td></tr><tr><td>斯坦·利普西（Stan Lipsey）</td><td><a href="/03_companies/水牛城新闻">水牛城新闻</a>管理者</td><td>成本控制出色，帮助报纸度过与Courier-Express的竞争</td></tr><tr><td>Murray Light</td><td><a href="/03_companies/水牛城新闻">水牛城新闻</a>主编</td><td>坚持高质量新闻标准</td></tr></tbody></table><blockquote><p>&quot;指定捐赠这个想法，就像很多对我们来说结果很好的想法，是<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>副董事长、蓝筹印花董事长查理·<a href="/04_people/查理·芒格">查理·芒格</a>想出来的。&quot; —— <a href="/search?q=1981年">1981年</a>股东信</p></blockquote><h2 id="最终清算与历史评价" tabindex="-1">最终清算与历史评价 <a class="header-anchor" href="#最终清算与历史评价" aria-label="Permalink to &quot;最终清算与历史评价&quot;">​</a></h2><h3 id="合并后的蓝筹印花" tabindex="-1">合并后的蓝筹印花 <a class="header-anchor" href="#合并后的蓝筹印花" aria-label="Permalink to &quot;合并后的蓝筹印花&quot;">​</a></h3><ul><li>1983年合并完成后，蓝筹印花作为独立公司实体仍然存续了一段时间</li><li>其主营业务（印花兑换）持续萎缩，最终完全停止运营</li><li>但其投资组合中的核心资产——<a href="/03_companies/喜诗糖果">喜诗糖果</a>和<a href="/03_companies/水牛城新闻">水牛城新闻</a>——全部转入<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>体系，继续运营至今（喜诗糖果）</li></ul><h3 id="历史意义" tabindex="-1">历史意义 <a class="header-anchor" href="#历史意义" aria-label="Permalink to &quot;历史意义&quot;">​</a></h3><ol><li><p><strong>投资理念的摇篮</strong>：通过蓝筹印花平台，巴菲特和芒格完成了从&quot;雪茄烟蒂&quot;到&quot;优质企业&quot;的理念跨越——<a href="/03_companies/喜诗糖果">喜诗糖果</a>是这一转变的最佳案例</p></li><li><p><strong>浮存金投资模式的成功</strong>：一家正在衰落的零售印花公司，凭借积累的浮存金，完成了对美国最优质糖果公司和报纸的收购，并最终整体并入美国最成功的投资帝国</p></li><li><p><strong>双层控股结构的经典运用</strong>：通过<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>→蓝筹印花→韦斯考→喜诗糖果的多层持股结构，用少量权益资本控制了大量实业资产</p></li><li><p><strong><a href="/04_people/查理·芒格">查理·芒格</a>的平台</strong>：芒格长期担任蓝筹印花董事长，这里是他实际参与伯克希尔系企业管理的核心阵地</p></li></ol><blockquote><p>&quot;历史就是这样，我们过去就是把留存投到更好business，克服了本来起点很差的问题。（起点就是<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>原来就是纺织，多元化零售原来就是百货，<a href="/03_companies/蓝筹印花">蓝筹印花</a>原来就是印花，现在这些核心业务规模都缩水了，只有我们把赚的钱投到更好business，我们才有今天。）&quot; —— <a href="/search?q=1984年">1984年</a>股东信</p></blockquote><h2 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h2><blockquote><p>&quot;过去一年左右，<a href="/03_companies/蓝筹印花">蓝筹印花</a>的交易印花业务出现大幅下滑，但其旗下的<a href="/03_companies/喜诗糖果">喜诗糖果</a>子公司，以及持股54%、主营储贷业务的韦斯科金融公司，均具备重要的盈利能力来源。&quot; —— <a href="/search?q=1973年">1973年</a>股东信</p></blockquote><blockquote><p>&quot;蓝筹印花持有<a href="/03_companies/喜诗糖果">喜诗糖果</a>和水牛城新闻，这些是我们最珍视的业务。&quot; —— <a href="/search?q=1981年">1981年</a>股东信</p></blockquote><blockquote><p>&quot;1972年以来，<a href="/03_companies/喜诗糖果">喜诗糖果</a>税前运营收益从420万美元增长到1,260万美元，几乎没有增加额外的资本投资。&quot; —— <a href="/search?q=1977年">1977年</a>股东信</p></blockquote><blockquote><p>&quot;合并简化了我们的报告，让股东更清楚看到伯克希尔的真实经济状况。&quot; —— <a href="/search?q=1983年">1983年</a>股东信</p></blockquote><blockquote><p>&quot;与此同时，Charlie于1977年结束了他的业务。他分配给合伙人的资产中，包括他合伙企业、伯克希尔和我共同控制的主要权益——蓝筹印花。蓝章也是我的合伙企业解散时分配的三只股票之一。&quot; —— <a href="/search?q=2020年">2020年</a>股东信</p></blockquote><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>1969年（解散信），1973年，1974年，1975年，1976年，1977年，1978年，1979年，1980年，1981年，1982年，1983年，1984年，1985年，2019年，2020年</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/喜诗糖果">喜诗糖果</a> - 蓝筹印花收购的旗舰资产</li><li><a href="/03_companies/水牛城新闻">水牛城新闻</a> - 蓝筹印花收购的另一核心资产</li><li><a href="/search?q=韦斯考金融">韦斯考金融</a> - 蓝筹印花持股80%的储贷公司</li><li><a href="/04_people/查理·芒格">查理·芒格</a> - 蓝筹印花长期董事长</li><li><a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a> - 蓝筹印花的最终归宿</li><li><a href="/search?q=商誉经济学">商誉经济学</a> - 1983年股东信附录，喜诗糖果是核心案例</li></ul><h2 id="相关信件" tabindex="-1">相关信件 <a class="header-anchor" href="#相关信件" aria-label="Permalink to &quot;相关信件&quot;">​</a></h2><ul><li><a href="./../01_letters/1969年/解散信">1969年（解散信）</a></li><li><a href="./../01_letters/1973年/翻译">1973年</a></li><li><a href="./../01_letters/1974年/翻译">1974年</a></li><li><a href="./../01_letters/1975年/翻译">1975年</a></li><li><a href="./../01_letters/1976年/翻译">1976年</a></li><li><a href="./../01_letters/1977年/翻译">1977年</a></li><li><a href="./../01_letters/1978年/翻译">1978年</a></li><li><a href="./../01_letters/1979年/翻译">1979年</a></li><li><a href="./../01_letters/1980年/翻译">1980年</a></li><li><a href="./../01_letters/1981年/翻译">1981年</a></li><li><a href="./../01_letters/1982年/翻译">1982年</a></li><li><a href="./../01_letters/1983年/翻译">1983年</a></li><li><a href="./../01_letters/1984年/翻译">1984年</a></li><li><a href="./../01_letters/1985年/翻译">1985年</a></li><li><a href="./../01_letters/2019年/翻译">2019年</a></li><li><a href="./../01_letters/2020年/翻译">2020年</a></li></ul><hr><p><em>最后更新：2026-04-16</em></p><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该公司在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/01_letters/1956年/翻译">/01_letters/1956年/翻译</a></li><li><a href="/01_letters/1957年/翻译">/01_letters/1957年/翻译</a></li><li><a href="/01_letters/2019年/翻译">/01_letters/2019年/翻译</a></li><li><a href="/01_letters/2020年/翻译">/01_letters/2020年/翻译</a></li></ul>',54)])])}const p=a(l,[["render",i]]);export{f as __pageData,p as default};
